"""`KK Teeth (tooth)`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = 'KK Teeth (tooth)'


def build(lib):
    t = lib.new_material(NAME, props={
            'use_backface_culling_lightprobe_volume': False,
            'diffuse_color': (1.0, 1.0, 1.0, 1.0),
            'specular_color': (0.0, 0.0, 0.0),
            'roughness': 1.0,
            'line_color': (0.0, 0.0, 0.0, 1.0),
        })

    t.node('NodeFrame', 'Frame.001', props={
        'location': (-456.0, 145.75),
        'width': 292.40613,
        'height': 236.74998,
        'label': 'Texture files',
        'use_custom_color': True,
        'color': (0.2901505, 0.6787529, 0.1812863),
        'label_size': 23,
    })
    t.node('NodeFrame', 'FrameInfo.001', props={
        'location': (-137.0, 145.75),
        'width': 830.563,
        'height': 365.75,
        'label': 'Shader',
        'use_custom_color': True,
        'color': (0.33001542, 0.4420454, 0.6247832),
        'label_size': 23,
    })
    t.node('NodeFrame', 'FrameInfo.002', props={
        'location': (717.0, 144.75),
        'width': 200.0,
        'height': 149.75,
        'label': 'Output',
        'use_custom_color': True,
        'color': (0.6247832, 0.073067226, 0.042191483),
        'label_size': 23,
    })
    t.node('NodeFrame', 'Frame', parent='FrameInfo.001', props={
        'location': (30.0, -43.75),
        'width': 453.65552,
        'height': 292.0,
        'label': 'Generate dark color by making it a little blue',
        'color': (0.604, 0.604, 0.604),
    })
    t.node('ShaderNodeGroup', 'combine', parent='FrameInfo.001', inputs={'Alpha mask': (1.0, 1.0, 1.0, 1.0), 'Alpha mask (alpha)': 1.0, 'Alpha mask (custom)': (1.0, 1.0, 1.0, 1.0), 'Force visibility': 1.0}, hide_inputs=('Alpha mask', 'Alpha mask (alpha)', 'Alpha mask (custom)', 'Force visibility', 'Force custom mask'), props={
        'node_tree': lib.group('.Combine colors'),
        'location': (538.04803, -45.546143),
        'width': 262.563,
    })
    t.node('ShaderNodeMix', 'Mix', parent='Frame', inputs={'B_Color': (0.665, 0.76, 0.95, 1.0)}, outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (29.703491, -40.121338),
        'width': 393.65552,
        'data_type': 'RGBA',
        'blend_type': 'MULTIPLY',
    })
    t.node('ShaderNodeOutputMaterial', 'out', parent='FrameInfo.002', hide_inputs=('Volume', 'Displacement', 'Thickness'), props={
        'location': (29.629028, -43.582336),
    })
    t.node('ShaderNodeGroup', 'textures', parent='Frame.001', hide_outputs=('Kage texture', 'Kage texture (alpha)'), props={
        'node_tree': lib.group('.Tex Face misc'),
        'location': (30.29712, -44.04077),
        'width': 232.40607,
    })

    t.link('textures', 'Toon shading', 'combine', 'Toon shading')
    t.link('textures', 'Main texture', 'combine', 'Light colors')
    t.link('combine', 'Result', 'out', 'Surface')
    t.link('textures', 'Main texture (alpha)', 'combine', 'Main texture (alpha)')
    t.link('textures', 'Main texture', 'Mix', 'A_Color')
    t.link('Mix', 'Result_Color', 'combine', 'Dark colors')
    return t
